/// H-28's verdict (ADR-0149), by the rule committed first over the arms' pinned tables: every
/// mapping learned in both arms — 123, 113, 122 and 119 of each mapping's last 128 from the
/// assignment and 124, 107, 122 and 114 from the mirrored assignment — no coupling past 1.30 of
/// its image's at any block's end, the excitatory sum outside the four couplings within the
/// band at every block's end, and each stimulus's mean value within a quarter of the reward of
/// three quarters of $2p - 1$ in every mapping. **H-28 is yes**, as ADR-0147 predicted.
pub(crate) const MISLED_1024: Misled = Misled {
    learning: Scheduled { learned: [[true, true, true, true], [true, true, true, true]], bounded: [true, true], over: [None, None], yes: true },
    left: [None, None],
    held: [true, true],
    expected: [[[true, true], [true, true], [true, true], [true, true]], [[true, true], [true, true], [true, true], [true, true]]],
    yes: true,
};
